//! M07-S1 pure recovery-state policy.
//! HOST supplies elapsed time, verified capture and durable-publication outcomes.
//! No timer, filesystem, codec, fingerprint computation or asset pinning lives here.

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CapturedAttempt {
    pub attempt_id: String,
    pub captured_revision: u64,
    pub captured_fingerprint: String,
    pub asset_manifest_digest: String,
}
#[derive(Debug, Clone, PartialEq, Eq)]

    Published,
    Failed,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RecoveryEventKind {
    Check {
        now_ms: u64,
        current_fingerprint: Option<String>,
        mutation_in_progress: bool,
    },
    BeginAttempt {
        capture: CapturedAttempt,
    },
    Complete {
        attempt_id: String,
        outcome: CompletionOutcome,
    },
    Close,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RecoveryEvent {

/// Returns a new state/action; it cannot mutate the caller or publish a snapshot.
/// Published is a trusted HOST receipt, not a claim authenticated by this policy.
pub fn transition_recovery(
    state: &RecoveryPolicyState,
    event: &RecoveryEvent,
) -> Result<RecoveryTransition, RecoveryPolicyError> {
    validate_id("state.project_id", &state.project_id)?;

RecoveryEventKind::Check {
    now_ms,
    current_fingerprint,
    mutation_in_progress,
} => {
    let elapsed = now_ms
        .checked_sub(state.last_check_ms)
        .ok_or(RecoveryPolicyError::TimeRegressed)?;
    if elapsed < 60000 {
        RecoveryAction::NotDue
    } else if state.inflight.is_some() || state.capture_requested {
        next.last_check_ms = *now_ms;
        RecoveryAction::WaitInFlight
    } else if *mutation_in_progress {
        RecoveryAction::DeferMutation
    } else {
        let current = current_fingerprint.as_ref().ok_or_else(|| {
            invalid(
                "current_fingerprint",
                "stable content fingerprint is required",
            )
        })?;
        next.last_check_ms = *now_ms;
        if state.successful_fingerprint.as_ref() == Some(current) {
            RecoveryAction::SkipUnchanged
        } else {
            next.capture_requested = true;
            RecoveryAction::RequestCapture
        }
    }
}

RecoveryEventKind::Complete {
    attempt_id,
    outcome,
} => {
    let capture = state
        .inflight
        .as_ref()
        .filter(|c| &c.attempt_id == attempt_id)
        .ok_or(RecoveryPolicyError::StaleAttempt)?;
    next.inflight = None;
    match outcome {
        CompletionOutcome::Published => {
            next.successful_fingerprint = Some(capture.captured_fingerprint.clone());
            RecoveryAction::BaselineAdvanced
        }
        CompletionOutcome::Failed => RecoveryAction::RetryPending,
    }
}

pub fn capture(&self) -> Result<ImmutableDocumentSnapshot, EditError> {
    self.check_editable()?;
    Ok(ImmutableDocumentSnapshot {
        document_uuid: self.state.document_uuid.clone(),
        session_uuid: self.state.session_uuid.clone(),
        revision: self.state.content_revision,
        content: self.state.content.clone(),
    })
}

pub fn acknowledge_formal_save(
    &mut self,
    captured: Revision,
    digest: &str,
) -> Result<SaveProjection, EditError> {
    self.check_ack(captured, digest, self.state.formal_baseline.as_ref())?;
    self.state.formal_baseline = Some(SavedContentBaseline {
        revision: captured,
        semantic_digest: digest.into(),
    });
    Ok(SaveProjection {
        captured_revision: captured,
        dirty: self.dirty(),
    })
}

pub fn acknowledge_recovery_save(
    &mut self,
    captured: Revision,
    digest: &str,
) -> Result<RecoveryProjection, EditError> {
    self.check_ack(captured, digest, self.state.snapshot_baseline.as_ref())?;
    self.state.snapshot_baseline = Some(SavedContentBaseline {
        revision: captured,
        semantic_digest: digest.into(),
    });
    Ok(RecoveryProjection {
        captured_revision: captured,
        needs_snapshot: self.state.content.semantic_digest != digest,
    })
}

fn check_ack(
    &self,
    captured: Revision,
    digest: &str,
    baseline: Option<&SavedContentBaseline>,
) -> Result<(), EditError> {
    self.check_editable()?;
    if !valid_digest(digest) {
        return Err(EditError::InvalidInput {
            field: "semanticDigest".into(),
        });
    }
    if captured.0 > self.state.content_revision.0
        || (captured == self.state.content_revision
            && digest != self.state.content.semantic_digest)
        || baseline.is_some_and(|saved| {
            captured.0 < saved.revision.0
                || (captured == saved.revision && digest != saved.semantic_digest)
        })
    {
        return Err(EditError::RevisionConflict);
    }
    Ok(())
}

}

